import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { test } from 'node:test'
import type { AppState, LearningCommand } from '../contracts/index.ts'
import { courseBundle } from '../content/catalog.ts'
import { lessonThreeBundle } from '../content/lesson-three.ts'
import { currentTask, transition } from '../learning/engine.ts'
import { loadState, migrateState, StorageError, validateState } from './index.ts'
import { indexedDBModel } from './test-idb.ts'

// Frozen before the third lesson was registered; generated by the real engine.
const baseline: AppState = JSON.parse(readFileSync(new URL('./fixtures/pre-lesson-three-schema5.json', import.meta.url), 'utf8'))
const NOW = '2026-11-10T10:00:00.000Z'
const FIRST = 'it-a1-lesson-01', SECOND = 'it-a1-lesson-02', THIRD = 'it-a1-lesson-03'
function apply(state: AppState, command: LearningCommand): AppState {
  const next = transition(state, command, courseBundle, NOW)
  validateState(next, courseBundle)
  return next
}

test('adding lesson three loads every field of the real two-lesson snapshot unchanged without a migration write', async () => {
  assert.equal(baseline.schemaVersion, 5)
  assert.equal(courseBundle.contentVersion, 'nuovo-espresso-a1-it-v1')
  assert.equal(baseline.contentVersion, courseBundle.contentVersion)
  assert.equal(Object.keys(baseline.progress).length, 35)
  assert.equal(baseline.attempts.length, 117)
  assert.equal(baseline.reverseReviews.length, 8)
  assert.equal(baseline.activeLessonId, SECOND)
  assert.ok(baseline.session!.draft.length > 0)
  assert.ok(baseline.savedSessions[FIRST].feedback)
  assert.ok(Object.keys(baseline.dailyActivity).length > 0)
  const original = structuredClone(baseline)
  validateState(baseline, courseBundle)
  const restored = migrateState(baseline, courseBundle)
  assert.notEqual(restored, baseline)
  assert.deepEqual(restored, original)
  assert.deepEqual(baseline, original)
  const model = indexedDBModel(baseline), previous = globalThis.indexedDB
  globalThis.indexedDB = model.factory
  try {
    model.failNextPut()
    assert.deepEqual(await loadState(courseBundle), original)
    assert.deepEqual(await loadState(courseBundle), original)
    assert.deepEqual(model.read(), original)
    assert.deepEqual(model.keys(), ['current'])
  } finally { globalThis.indexedDB = previous }
})

test('switching all three lessons preserves the old paused draft, feedback, queues, history and schedules', () => {
  const original = structuredClone(baseline)
  let state = migrateState(baseline, courseBundle)
  state = apply(state, { type: 'select-lesson', lessonId: THIRD })
  assert.equal(state.session, null)
  assert.deepEqual(state.savedSessions[SECOND], original.session)
  assert.deepEqual(state.savedSessions[FIRST], original.savedSessions[FIRST])
  assert.deepEqual(state.progress, original.progress)
  assert.deepEqual(state.attempts, original.attempts)
  assert.deepEqual(state.reverseReviews, original.reverseReviews)
  assert.deepEqual(state.reverseProgress, original.reverseProgress)
  assert.deepEqual(state.dailyActivity, original.dailyActivity)
  state = apply(state, { type: 'start-session', sessionId: 'after-third-addition', seed: 317 })
  assert.equal(state.session!.lessonId, THIRD)
  assert.ok(state.session!.queue.filter(task => task.kind === 'flashcard').length <= 5)
  assert.ok(state.session!.queue.filter(task => task.kind === 'flashcard').every(task => lessonThreeBundle.lesson.introducedEntryIds.includes(task.entryId)))
  for (const [id, progress] of Object.entries(original.progress)) assert.deepEqual(state.progress[id], progress)
  const newIds = Object.keys(state.progress).filter(id => !original.progress[id])
  assert.ok(newIds.every(id => lessonThreeBundle.lesson.introducedEntryIds.includes(id)))
  const third = { ...structuredClone(state.session!), state: 'paused' as const }
  for (const lessonId of [FIRST, SECOND, THIRD, SECOND, FIRST]) {
    state = apply(state, { type: 'select-lesson', lessonId })
    const expected = lessonId === FIRST ? original.savedSessions[FIRST] : lessonId === SECOND ? original.session : third
    assert.deepEqual(state.session, expected)
    assert.deepEqual(state.attempts, original.attempts)
    assert.deepEqual(state.reverseReviews, original.reverseReviews)
  }
  state = apply(state, { type: 'select-lesson', lessonId: SECOND })
  assert.equal(state.session!.draft, original.session!.draft)
  assert.deepEqual(state.session!.queue, original.session!.queue)
  assert.equal(currentTask(state)!.taskId, original.session!.queue[original.session!.cursor].taskId)
  assert.deepEqual(state.savedSessions[FIRST].feedback, original.savedSessions[FIRST].feedback)
  assert.deepEqual(migrateState(state, courseBundle), state)
  assert.deepEqual(baseline, original)
})

test('third lesson preserves rejection of foreign schema and content without mutating old data', () => {
  for (const foreign of [
    { ...structuredClone(baseline), schemaVersion: 4 },
    { ...structuredClone(baseline), schemaVersion: 6 },
    { ...structuredClone(baseline), contentVersion: 'nuovo-espresso-a1-it-v2' },
    { ...structuredClone(baseline), contentVersion: 'course-a1-lessons-01-04-v1' },
  ]) {
    const original = structuredClone(foreign)
    assert.throws(() => migrateState(foreign, courseBundle), StorageError)
    assert.deepEqual(foreign, original)
  }
})
